// Entry for the redesign preview Worker (wrangler.next.jsonc).
// Runs the production worker unchanged, but serves the static files from a module bundled
// into the script (generated by `npm run build:next`) instead of a Workers Assets upload.
// This keeps the preview deployable with a plain API token; production still uses Assets.
import app from './worker.js';
import { files } from './.next-build/assets.mjs';

const types = {
  html: 'text/html; charset=utf-8',
  css: 'text/css; charset=utf-8',
  js: 'text/javascript; charset=utf-8',
  json: 'application/json',
  webmanifest: 'application/manifest+json',
  png: 'image/png',
  webp: 'image/webp',
  svg: 'image/svg+xml',
  ico: 'image/x-icon',
  txt: 'text/plain; charset=utf-8',
};

function body(file) {
  if (file.text !== undefined) return file.text;
  const raw = atob(file.base64);
  const bytes = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
  return bytes;
}

// Mirrors the Workers Assets default html_handling ("auto-trailing-slash") for this site's files.
export function serveAsset(request, table = files) {
  const url = new URL(request.url);
  if (!['GET', 'HEAD'].includes(request.method))
    return new Response('Method not allowed', { status: 405 });
  let path = decodeURIComponent(url.pathname).replace(/^\/+/, '');
  if (path.endsWith('.html') && table[path]) {
    url.pathname = '/' + path.replace(/(^|\/)index\.html$/, '$1').replace(/\.html$/, '');
    return Response.redirect(url.href, 307);
  }
  let name = table[path] ? path : table[path + '.html'] ? path + '.html' : null;
  if (!name && (path === '' || path.endsWith('/')) && table[path + 'index.html'])
    name = path + 'index.html';
  if (!name) return new Response('Not found', { status: 404 });
  const ext = name.split('.').pop();
  return new Response(request.method === 'HEAD' ? null : body(table[name]), {
    headers: {
      'Content-Type': types[ext] || 'application/octet-stream',
      'Cache-Control': 'public, max-age=0, must-revalidate',
    },
  });
}

export default {
  scheduled: app.scheduled,
  fetch(request, env, ctx) {
    return app.fetch(request, { ...env, ASSETS: { fetch: serveAsset } }, ctx);
  },
};
